for ln in T[663915:668451].split('\n'):
    if ln.strip(): paras.append((663915+i,663915+i+len(ln)))
    i+=len(ln)+1
cov=sum(1 for a,b in paras if any(min(b,y)-max(a,x)>0 for x,y in R))
print('quoteRefs',len(R),'paras',len(paras),'covered',cov)
